import pandas as pd
from collections import defaultdict

def test():
    """
    Calculates the vocabulary size of 3-mers across all datasets.
    """
    try:
        dataset_dirs = [
            "Isoform", "CRISPROffTarget", "Modification", "CRISPROnTarget",
            "ProgrammableRNASwitches", "MeanRibosomeLoading", "NoncodingRNAFamily"
        ]

        vocabulary = set()
        k = 3 # K-mer size

        for data_dir in dataset_dirs:
            path = f"storage/system/data/{data_dir}/train.csv"
            df = pd.read_csv(path)

            # Find the sequence column (common names)
            seq_col = None
            if 'seq' in df.columns:
                seq_col = 'seq'
            elif 'sequence' in df.columns:
                seq_col = 'sequence'

            if seq_col:
                sequences = df[seq_col].dropna()
            elif 'sgrna' in df.columns and 'target' in df.columns:
                sequences = df['sgrna'].dropna() + df['target'].dropna()
            else:
                continue

            for seq in sequences:
                if len(seq) < k:
                    continue
                for i in range(len(seq) - k + 1):
                    kmer = seq[i:i+k].upper()
                    vocabulary.add(kmer)

        # Add a padding token and an unknown token
        vocabulary.add("<PAD>")
        vocabulary.add("<UNK>")

        results = [
            "--- K-mer (3-mer) Vocabulary Analysis ---",
            f"Total unique 3-mers found: {len(vocabulary) - 2}",
            f"Vocabulary size (including <PAD>, <UNK>): {len(vocabulary)}"
        ]
        return "\n".join(results)

    except Exception as e:
        return f"An error occurred during analysis: {str(e)}"
